package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import java.sql.Timestamp;import java.security.SecureRandom;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.planning.recurrence.v1.*;
/** Series and existing child Schedule writes share one Planning-local transaction. */
final class RecurrenceStore {
 record LinkedOccurrence(int ordinal,UUID scheduleId,String startsAt,String endsAt,String startsLocal,String endsLocal,String startsOffset,String endsOffset){}
 record Series(UUID recurrenceId,UUID spaceId,String visibility,String state,long version,RecurrenceRules.Input input,String previewHash,List<LinkedOccurrence> occurrences,int retiredFromOrdinal,String cancellationHash,String createdAt,String updatedAt){}
 record Creation(Series recurrence,boolean replay){}
 record Summary(UUID recurrenceId,String title,String frequency,int interval,int count,String timeZone,String state,long version,String updatedAt){}
 record Page(UUID spaceId,String state,List<Summary> items,String nextAfter){}
 record Revision(UUID revisionId,UUID recurrenceId,long version,UUID actorId,String occurredAt,Series snapshot){}
 record Candidate(int ordinal,UUID scheduleId,long version,String title,String startsAt,String endsAt,String timeZone,String startsLocal,String endsLocal,String startsOffset,String endsOffset,UUID taskId){}
 record Cancellation(UUID spaceId,UUID recurrenceId,long version,int fromOrdinal,List<Candidate> items,String cancellationHash){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final ScheduleStore schedules;private final Clock clock;private final UuidV7 ids;private final SecureRandom random=new SecureRandom();private final JsonMapper json=JsonMapper.builder().build();
 RecurrenceStore(DataSource ds,Clock clock){jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(60);schedules=new ScheduleStore(ds,clock);this.clock=clock;ids=new UuidV7(clock);}
 static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Recurrence unavailable");}
 private void task(UUID space,UUID id){if(id==null)return;if(jdbc.query("SELECT task_id FROM task WHERE space_id=? AND task_id=? AND state='ACTIVE' FOR UPDATE",(rs,n)->rs.getObject(1,UUID.class),space,id).isEmpty())throw ScheduleStore.missing();}
 RecurrenceRules.Preview preview(UUID space,RecurrenceRules.Input input){RecurrenceRules.input(input);task(space,input.taskId());return RecurrenceRules.preview(space,input);}
 Creation create(UUID space,UUID actor,String key,RecurrenceRules.Input input,String previewHash,String trace){ScheduleRules.id(space);ScheduleRules.id(actor);GoalRules.trace(trace);RecurrenceRules.input(input);RecurrenceRules.hash(previewHash);if(key==null||!key.matches("[0-9a-f]{32}"))throw ScheduleRules.bad();String fingerprint=RecurrenceRules.hash(List.of(input,previewHash));return tx.execute(s->{var id=ids.next();var now=clock.instant();int added=jdbc.update("INSERT INTO recurrence VALUES (?,?,'PRIVATE','ACTIVE',1,?,?,?,?,?) ON CONFLICT(space_id,request_key) DO NOTHING",id,space,input.title(),key,fingerprint,Timestamp.from(now),Timestamp.from(now));if(added==0){var original=jdbc.query("SELECT g.request_hash,r.snapshot::text FROM recurrence g JOIN recurrence_revision r ON r.recurrence_id=g.recurrence_id AND r.version=1 WHERE g.space_id=? AND g.request_key=?",(rs,n)->Map.entry(rs.getString(1),rs.getString(2)),space,key);if(original.size()!=1)throw new IllegalStateException("Original recurrence missing");if(!fingerprint.equals(original.getFirst().getKey()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Creation intent differs");return new Creation(json.readValue(original.getFirst().getValue(),Series.class),true);}var plan=RecurrenceRules.preview(space,input);if(!plan.issues().isEmpty())throw ScheduleRules.bad();if(!previewHash.equals(plan.previewHash()))throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Preview changed; preview again");task(space,input.taskId());var children=new ArrayList<LinkedOccurrence>();for(var p:plan.occurrences()){byte[] bytes=new byte[16];random.nextBytes(bytes);var child=schedules.create(space,actor,HexFormat.of().formatHex(bytes),new ScheduleStore.Input(input.title(),input.description(),p.startsAt(),p.endsAt(),input.timeZone(),input.taskId()),trace).schedule();if(!child.startsLocal().equals(p.startsLocal())||!child.endsLocal().equals(p.endsLocal())||!child.startsOffset().equals(p.startsOffset())||!child.endsOffset().equals(p.endsOffset()))throw new IllegalStateException("Timezone changed during creation");jdbc.update("INSERT INTO recurrence_occurrence VALUES (?,?,?,?)",id,space,p.ordinal(),child.scheduleId());children.add(new LinkedOccurrence(p.ordinal(),child.scheduleId(),p.startsAt(),p.endsAt(),p.startsLocal(),p.endsLocal(),p.startsOffset(),p.endsOffset()));}var value=new Series(id,space,"PRIVATE","ACTIVE",1,input,previewHash,List.copyOf(children),0,null,now.toString(),now.toString());revision(value,actor,trace,"RecurrenceCreated");return new Creation(value,false);});}
 private Series current(UUID space,UUID id,boolean lock){ScheduleRules.id(space);ScheduleRules.id(id);if(lock&&jdbc.query("SELECT recurrence_id FROM recurrence WHERE space_id=? AND recurrence_id=? FOR UPDATE",(rs,n)->rs.getObject(1,UUID.class),space,id).isEmpty())throw missing();var rows=jdbc.query("SELECT r.snapshot::text FROM recurrence g JOIN recurrence_revision r ON r.recurrence_id=g.recurrence_id AND r.version=g.version WHERE g.space_id=? AND g.recurrence_id=?",(rs,n)->json.readValue(rs.getString(1),Series.class),space,id);if(rows.isEmpty())throw missing();var v=rows.getFirst();if(!v.spaceId().equals(space)||!v.recurrenceId().equals(id)||!v.visibility().equals("PRIVATE"))throw new IllegalStateException("Recurrence scope mismatch");return v;}
 Series get(UUID space,UUID id){return current(space,id,false);}
 private Cancellation cancellation(Series value,int from,boolean lock){if(from<1||from>value.input().count())throw ScheduleRules.bad();if(lock)jdbc.query("SELECT s.schedule_id FROM recurrence_occurrence o JOIN schedule s ON s.schedule_id=o.schedule_id AND s.space_id=o.space_id WHERE o.recurrence_id=? AND o.space_id=? AND o.ordinal>=? ORDER BY s.schedule_id FOR UPDATE OF s",(rs,n)->rs.getObject(1,UUID.class),value.recurrenceId(),value.spaceId(),from);var rows=jdbc.query("SELECT o.ordinal,r.snapshot::text FROM recurrence_occurrence o JOIN schedule s ON s.schedule_id=o.schedule_id AND s.space_id=o.space_id JOIN schedule_revision r ON r.schedule_id=s.schedule_id AND r.version=s.version WHERE o.recurrence_id=? AND o.space_id=? AND o.ordinal>=? AND s.state='ACTIVE' ORDER BY o.ordinal",(rs,n)->{var c=json.readValue(rs.getString(2),ScheduleStore.Schedule.class);if(!c.spaceId().equals(value.spaceId()))throw new IllegalStateException("Child scope mismatch");return new Candidate(rs.getInt(1),c.scheduleId(),c.version(),c.title(),c.startsAt(),c.endsAt(),c.timeZone(),c.startsLocal(),c.endsLocal(),c.startsOffset(),c.endsOffset(),c.taskId());},value.recurrenceId(),value.spaceId(),from);var result=new Cancellation(value.spaceId(),value.recurrenceId(),value.version(),from,List.copyOf(rows),null);return new Cancellation(result.spaceId(),result.recurrenceId(),result.version(),from,result.items(),RecurrenceRules.hash(result));}
 Cancellation cancellation(UUID space,UUID id,int from){var v=current(space,id,false);if(!v.state().equals("ACTIVE"))throw missing();return cancellation(v,from,false);}
 Series cancel(UUID space,UUID id,UUID actor,long expected,int from,String hash,String trace){ScheduleRules.id(actor);GoalRules.trace(trace);RecurrenceRules.hash(hash);if(expected<1)throw ScheduleRules.bad();return tx.execute(s->{var prior=current(space,id,true);if(prior.state().equals("RETIRED")){if(prior.retiredFromOrdinal()==from&&hash.equals(prior.cancellationHash())&&(expected==prior.version()||expected==prior.version()-1))return prior;throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Recurrence already changed");}if(prior.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Recurrence changed");var plan=cancellation(prior,from,true);if(!hash.equals(plan.cancellationHash()))throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Occurrences changed; review again");for(var c:plan.items())schedules.change(space,c.scheduleId(),actor,c.version(),null,true,trace);var now=clock.instant();var v=new Series(id,space,"PRIVATE","RETIRED",Math.addExact(prior.version(),1),prior.input(),prior.previewHash(),prior.occurrences(),from,hash,prior.createdAt(),now.toString());jdbc.update("UPDATE recurrence SET state='RETIRED',version=?,updated_at=? WHERE recurrence_id=?",v.version(),Timestamp.from(now),id);revision(v,actor,trace,"RecurrenceRetired");return v;});}
 Page list(UUID space,String state,String after,int limit){ScheduleRules.id(space);if(!Set.of("ACTIVE","RETIRED").contains(state)||limit<1||limit>100)throw ScheduleRules.bad();UUID position=null;if(after!=null){try{String raw=new String(Base64.getUrlDecoder().decode(after),java.nio.charset.StandardCharsets.US_ASCII);var parts=raw.split("\\|",-1);if(!after.matches("[A-Za-z0-9_-]{1,256}")||parts.length!=3||!parts[0].equals(space.toString())||!parts[1].equals(state)||!Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(java.nio.charset.StandardCharsets.US_ASCII)).equals(after))throw ScheduleRules.bad();position=ScheduleRules.id(parts[2]);}catch(IllegalArgumentException e){throw ScheduleRules.bad();}}var rows=jdbc.query("SELECT r.snapshot::text FROM recurrence g JOIN recurrence_revision r ON r.recurrence_id=g.recurrence_id AND r.version=g.version WHERE g.space_id=? AND g.state=?"+(position==null?"":" AND g.recurrence_id>?")+" ORDER BY g.recurrence_id LIMIT ?",(rs,n)->{var v=json.readValue(rs.getString(1),Series.class);return new Summary(v.recurrenceId(),v.input().title(),v.input().frequency(),v.input().interval(),v.input().count(),v.input().timeZone(),v.state(),v.version(),v.updatedAt());},position==null?new Object[]{space,state,limit+1}:new Object[]{space,state,position,limit+1});var items=List.copyOf(rows.subList(0,Math.min(rows.size(),limit)));String next=rows.size()>limit?Base64.getUrlEncoder().withoutPadding().encodeToString((space+"|"+state+"|"+items.getLast().recurrenceId()).getBytes(java.nio.charset.StandardCharsets.US_ASCII)):null;return new Page(space,state,items,next);}
 List<Revision> history(UUID space,UUID id,long before,int limit){current(space,id,false);if(before<1||limit<1||limit>10)throw ScheduleRules.bad();return jdbc.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM recurrence_revision WHERE recurrence_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),id,rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Series.class)),id,before,limit);}
 private void revision(Series v,UUID actor,String trace,String type){UUID revision=ids.next(),event=ids.next();var now=Instant.parse(v.updatedAt());jdbc.update("INSERT INTO recurrence_revision VALUES (?,?,?,?,?,?::jsonb)",revision,v.recurrenceId(),v.version(),actor,Timestamp.from(now),json.writeValueAsString(v));var i=v.input();var p=RecurrenceChangedPayloadV1.newBuilder().setRecurrenceId(v.recurrenceId().toString()).setRevisionId(revision.toString()).setVersion(v.version()).setVisibility("PRIVATE").setState(v.state()).setTitle(i.title()).setDescription(i.description()).setStartsLocal(i.startsLocal()).setEndsLocal(i.endsLocal()).setTimeZone(i.timeZone()).setTaskId(i.taskId()==null?"":i.taskId().toString()).setFrequency(i.frequency()).setInterval(i.interval()).setCount(i.count()).setStartsOverlap(i.startsOverlap()).setEndsOverlap(i.endsOverlap()).setPreviewHash(v.previewHash()).setCreatedAt(v.createdAt()).setUpdatedAt(v.updatedAt()).setRetiredFromOrdinal(v.retiredFromOrdinal()).setCancellationHash(v.cancellationHash()==null?"":v.cancellationHash());for(var c:v.occurrences())p.addOccurrences(RecurrenceOccurrenceV1.newBuilder().setOrdinal(c.ordinal()).setScheduleId(c.scheduleId().toString()).setStartsAt(c.startsAt()).setEndsAt(c.endsAt()).setStartsLocal(c.startsLocal()).setEndsLocal(c.endsLocal()).setStartsOffset(c.startsOffset()).setEndsOffset(c.endsOffset()));var e=RecurrenceEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("planning-service").setAggregateType("Recurrence").setAggregateId(v.recurrenceId().toString()).setSpaceId(v.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(p.build().toByteString()).build();jdbc.update("INSERT INTO outbox_event VALUES (?,'recurrence',?,?,?,?, 'planning','recurrence-events','1',?)",event,v.recurrenceId(),type,Timestamp.from(now),trace,e.toByteArray());}
}
